import json,os,stat
paths=['/','/home','/home/alex','/home/alex/work','/run','/run/user','/run/user/1000']
rows=[]
for p in paths:
 try:
  s=os.lstat(p);rows.append({'path':p,'device':s.st_dev,'inode':s.st_ino,'uid':s.st_uid,'gid':s.st_gid,'mode':stat.S_IMODE(s.st_mode),'type_dir':stat.S_ISDIR(s.st_mode),'symlink':stat.S_ISLNK(s.st_mode)})
 except FileNotFoundError:rows.append({'path':p,'absent':True})
print(json.dumps({'scope':'fixed output ancestor metadata only','uid':os.getuid(),'euid':os.geteuid(),'rows':rows,'writes':0}))
